using System;namespace HR.Domain.Entities{    public class AdministrativeDepartment    {        public Guid Id { get; set; }        public Guid BranchId { get; set; }        public string DepartmentName { get; set; } = string.Empty;        public string DepartmentCode { get; set; } = string.Empty;        public string? Description { get; set; }        public bool IsActive { get; set; } = true;        public DateTime CreatedAt { get; set; } = DateTime.UtcNow;        public DateTime? UpdatedAt { get; set; }        public Branch Branch { get; set; } = null!;    }}